insert into storage.buckets (id, name, public) values ('brand-assets','brand-assets',true) on conflict (id) do update set public = excluded.public;
create policy "brand assets read" on storage.objects for select using (bucket_id = 'brand-assets');
create policy "brand assets upload own folder" on storage.objects for insert to authenticated with check (bucket_id = 'brand-assets' and (storage.foldername(name))[1] = (select auth.uid()::text));
create policy "brand assets update own folder" on storage.objects for update to authenticated using (bucket_id = 'brand-assets' and (storage.foldername(name))[1] = (select auth.uid()::text)) with check (bucket_id = 'brand-assets' and (storage.foldername(name))[1] = (select auth.uid()::text));
create policy "brand assets delete own folder" on storage.objects for delete to authenticated using (bucket_id = 'brand-assets' and (storage.foldername(name))[1] = (select auth.uid()::text));